import { splitSemicolonList, toIsoDate, toStringId } from "../../utils/string-utils.js";
export function mapVoluntarioToResponse(record) {
    return {
        id_voluntario: toStringId(record.id),
        profissional_id: record.profissionalId ? toStringId(record.profissionalId) : undefined,
        profissional_nome: record.profissional?.nomeCompleto ?? undefined,
        profissional_categoria: record.profissional?.categoria ?? undefined,
        nome_completo: record.nomeCompleto,
        cpf: record.cpf,
        rg: record.rg ?? undefined,
        foto_3x4: record.foto3x4 ?? undefined,
        data_nascimento: toIsoDate(record.dataNascimento),
        genero: record.genero ?? undefined,
        profissao: record.profissao ?? undefined,
        motivacao: record.motivacao ?? undefined,
        telefone: record.telefone ?? undefined,
        email: record.email,
        cidade: record.cidade ?? undefined,
        estado: record.estado ?? undefined,
        area_interesse: record.areaInteresse ?? undefined,
        habilidades: record.habilidades ?? undefined,
        idiomas: record.idiomas ?? undefined,
        linkedin: record.linkedin ?? undefined,
        status: record.status ?? "ATIVO",
        disponibilidade_dias: splitSemicolonList(record.disponibilidadeDias),
        disponibilidade_periodos: splitSemicolonList(record.disponibilidadePeriodos),
        carga_horaria_semanal: record.cargaHorariaSemanal ?? undefined,
        presencial: record.presencial ?? false,
        remoto: record.remoto ?? false,
        inicio_previsto: toIsoDate(record.inicioPrevisto),
        observacoes: record.observacoes ?? undefined,
        documento_identificacao: record.documentoIdentificacao ?? undefined,
        comprovante_endereco: record.comprovanteEndereco ?? undefined,
        aceite_voluntariado: record.aceiteVoluntariado,
        aceite_imagem: record.aceiteImagem,
        assinatura_digital: record.assinaturaDigital ?? undefined,
        cep: record.endereco?.cep ?? undefined,
        logradouro: record.endereco?.logradouro ?? undefined,
        numero: record.endereco?.numero ?? undefined,
        complemento: record.endereco?.complemento ?? undefined,
        bairro: record.endereco?.bairro ?? undefined,
        ponto_referencia: record.endereco?.pontoReferencia ?? undefined,
        municipio: record.endereco?.cidade ?? undefined,
        zona: record.endereco?.zona ?? undefined,
        subzona: record.endereco?.subzona ?? undefined,
        uf: record.endereco?.estado ?? undefined,
        data_cadastro: record.criadoEm.toISOString(),
        data_atualizacao: record.atualizadoEm.toISOString()
    };
}
